@@ -39,4 +39,51 @@ export async function createOrder(db: PGlite, customerId: number, amountCents: n
 }

+// ---------------------------------------------------------------------------
+// In-memory response cache for GET /stats/top-customers
+// TTL is 60 seconds by default; tests may override via the exported constant.
+// ---------------------------------------------------------------------------
+
+export const CACHE_TTL_MS = 60_000;
+
+interface CacheEntry {
+  value: TopCustomer[];
+  expiresAt: number;
+}
+
+// One cache map per module load. Each buildServer() call shares this cache so
+// that concurrent requests collapse onto the same in-flight query (see the
+// inflight map below) and hot restarts pick up immediately.
+const cache = new Map<number, CacheEntry>();
+const inflight = new Map<number, Promise<TopCustomer[]>>();
+
+/** Exposed so tests can invalidate entries without waiting for real TTL. */
+export function bustCache(): void {
+  cache.clear();
+}
+
+async function cachedTopCustomers(db: PGlite, limit: number): Promise<TopCustomer[]> {
+  const now = Date.now();
+  const entry = cache.get(limit);
+  if (entry && now < entry.expiresAt) {
+    return entry.value;
+  }
+
+  // Collapse concurrent requests for the same limit into one DB query.
+  let pending = inflight.get(limit);
+  if (!pending) {
+    pending = topCustomers(db, limit).then((rows) => {
+      cache.set(limit, { value: rows, expiresAt: Date.now() + CACHE_TTL_MS });
+      inflight.delete(limit);
+      return rows;
+    }).catch((err) => {
+      inflight.delete(limit);
+      throw err;
+    });
+    inflight.set(limit, pending);
+  }
+
+  return pending;
+}
+
 function send(res: ServerResponse, status: number, body: unknown): void {
   res.writeHead(status, { "content-type": "application/json" });
@@ -61,5 +108,5 @@ export function buildServer(db: PGlite): Server {
       if (req.method === "GET" && url.pathname === "/stats/top-customers") {
         const limit = Math.min(Math.max(Number(url.searchParams.get("limit") ?? 10), 1), 100);
-        return send(res, 200, await topCustomers(db, limit));
+        return send(res, 200, await cachedTopCustomers(db, limit));
       }

diff --git a/demo/orders-api/src/db.ts b/demo/orders-api/src/db.ts
index fa3c0a9..bbe2afe 100644
--- a/demo/orders-api/src/db.ts
+++ b/demo/orders-api/src/db.ts
@@ -40,4 +40,24 @@ export async function openDb(): Promise<PGlite> {
     ANALYZE;
   `);
+
+  // Materialized view: precomputed top-customers ranking (no time filter —
+  // the view itself stores the rolling-30-day aggregation so every refresh
+  // re-evaluates the window cheaply against a fresh snapshot).
+  await db.exec(`
+    CREATE MATERIALIZED VIEW mv_top_customers AS
+    SELECT c.id AS customer_id,
+           c.name,
+           sum(o.amount_cents)::int AS revenue_cents,
+           count(*)::int           AS orders
+    FROM orders o
+    JOIN customers c ON c.id = o.customer_id
+    WHERE o.status = 'paid'
+      AND o.created_at > now() - interval '30 days'
+    GROUP BY c.id, c.name
+    ORDER BY revenue_cents DESC;
+
+    CREATE UNIQUE INDEX ON mv_top_customers (customer_id);
+  `);
+
   return db;
 }
