index 0000000..3fc1d0f
--- /dev/null
+++ b/demo/orders-api/src/matview.ts
@@ -0,0 +1,23 @@
+import type { PGlite } from "@electric-sql/pglite";
+
+const REFRESH_INTERVAL_MS = 5_000;
+
+/**
+ * Starts a background interval that refreshes mv_top_customers every 5 s.
+ * Returns a stop function that clears the interval (call it in tests/shutdown).
+ *
+ * CONCURRENTLY is used so reads are never blocked during refresh.
+ * It requires the unique index on customer_id that openDb() creates.
+ */
+export function startRefresh(db: PGlite): () => void {
+  const timer = setInterval(() => {
+    db.exec("REFRESH MATERIALIZED VIEW CONCURRENTLY mv_top_customers").catch(
+      (err) => console.error("[matview] refresh error:", err),
+    );
+  }, REFRESH_INTERVAL_MS);
+
+  // Let Node exit even if the interval is still pending (belt-and-suspenders).
+  if (typeof timer.unref === "function") timer.unref();
+
+  return () => clearInterval(timer);
+}
